const userProfile = `-- name: UserProfile :one
SELECT
  u.id,
  u.first_name,
  u.last_name,
  u.phone_number,
  u.status,
  u.created_at,
  u.updated_at,
  r.id AS role_id,
  r.name AS role_name,
  u.user_name AS user_name
FROM users u
JOIN role r ON u.role_id = r.id
WHERE u.id = $1
`

type UserProfileRow struct {
	ID          uuid.UUID `json:"id"`
	FirstName   string    `json:"first_name"`
	LastName    string    `json:"last_name"`
	PhoneNumber string    `json:"phone_number"`
	Status      UserState `json:"status"`
	CreatedAt   time.Time `json:"created_at"`
	UpdatedAt   time.Time `json:"updated_at"`
	RoleID      int32     `json:"role_id"`
	RoleName    string    `json:"role_name"`
	UserName    string    `json:"user_name"`
}

func (q *Queries) UserProfile(ctx context.Context, id uuid.UUID) (UserProfileRow, error) {
	row := q.db.QueryRow(ctx, userProfile, id)
	var i UserProfileRow
	err := row.Scan(
		&i.ID,
		&i.FirstName,
		&i.LastName,
		&i.PhoneNumber,
		&i.Status,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.RoleID,
		&i.RoleName,
		&i.UserName,
	)
	return i, err
}
